parameters.jsCode:
const body = $json.body ?? $json;
const action = body.action;
const issue = body.issue;
const repository = body.repository;

const isGitHubIssueEvent = Boolean(issue?.number && issue?.title && repository?.full_name);
const shouldTriage = isGitHubIssueEvent && action === 'opened';

return [{
  json: {
    isValid: isGitHubIssueEvent,
    shouldTriage,
    action,
    issue: issue ?? {},
    repository: repository ?? {},
    sender: body.sender ?? {},
    deliveryId: $headers['x-github-delivery'] ?? null
  }
}];

const source = $('Validate GitHub Event').first().json;
const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('AI response did not contain message content');

let result;
try {
  result = JSON.parse(content);
} catch (error) {
  throw new Error(`AI response was not valid JSON: ${error.message}`);
}

const allowedCategories = new Set(['bug', 'feature', 'documentation', 'question', 'security', 'other']);
const allowedPriorities = new Set(['low', 'medium', 'high', 'critical']);
const allowedLabels = new Set(['bug', 'feature', 'documentation', 'question', 'security', 'priority:high', 'priority:critical', 'needs-triage']);
const category = allowedCategories.has(result.category) ? result.category : 'other';
const priority = allowedPriorities.has(result.priority) ? result.priority : 'medium';
const labels = Array.isArray(result.labels) ? result.labels.filter((label) => allowedLabels.has(label)) : [];
if (!labels.includes(category) && category !== 'other') labels.push(category);
if (priority === 'high' || priority === 'critical') {
  const priorityLabel = `priority:${priority}`;
  if (!labels.includes(priorityLabel)) labels.push(priorityLabel);
}
if (!labels.length) labels.push('needs-triage');

return [{
  json: {
    ...source,
    triage: {
      category,
      priority,
      labels,
      summary: String(result.summary || 'Automated triage completed').slice(0, 240),
      response: String(result.response || 'Thanks for opening this issue. It has been triaged for review.').slice(0, 600)
    }
  }
}];

